basicCode.vanilla:
import { createFlowGraph } from '@/components/ui/flow-graph';

const flowGraph = createFlowGraph({
  nodes: nos,
  edges: arestas,
  status: 'running',
  labels: rotulos,
});

// Sem nó nenhum não há grafo, e a fábrica devolve nada.
if (flowGraph) document.querySelector('#app')?.append(flowGraph);

basicCode.react:
import { FlowGraph } from "@/components/ui/flow-graph";

<FlowGraph
