withLabelsCode.vanilla:
// Três coisas, e as três são de interface — nenhuma delas é a fala do agente.
//
// O NOME DA CAMADA QUE ROLA é obrigatório: o grafo é mais largo que a conversa,
// então ele rola, e o que rola é parada de teclado. Sem nome, quem chega ali
// ouvindo não sabe onde entrou — e duas peças destas na mesma tela com o mesmo
// nome são duas paradas indistinguíveis.
//
// O MOLDE DA DEPENDÊNCIA leva a lista de rótulos no lugar marcado: a palavra que
// apresenta a lista é do idioma, e os rótulos são dado.
//
// A PALAVRA DE CADA ESTADO é o que chega a quem não vê a forma da marca.
const rotulos = {
  region: 'Fluxo do atendimento',
  dependsOn: 'Depende de {sources}.',
  state: {
    pending: 'Por fazer',
    running: 'Em andamento',
    done: 'Concluído',
    failed: 'Falhou',
  },
};

