// expressão de template só enxerga membro, e um binding para uma constante
// importada não resolve.
readonly nos: readonly FlowNode[] = [/* os nós do fluxo */];
readonly arestas: readonly FlowEdge[] = [/* as dependências */];

readonly revelados = signal(1);

readonly visiveis = computed(() => this.nos.slice(0, this.revelados()));

