// No template, os quatro entram como os membros que são:
//
//   <div
//     ndsFlowGraph
//     [nodes]="visiveis()"
//     [edges]="arestas"
//     [status]="estado()"
//     [labels]="rotulos"
//   ></div>

customizationCode.web:
.nds-flow-graph {
  /* A largura MÍNIMA de coluna, e é ela que decide quando o grafo passa a ser
     mais largo que a conversa e a camada começa a rolar. Mínima e não fixa: as
     colunas repartem a largura disponível em partes iguais e só param de
     encolher aqui. */
  --flow-graph-column-min: var(--spacing-16);
}

